from number_lines_core import *
from ail import write_text
import sys

def main() -> int:
    if len(sys.argv) != 3:
        print('usage: number_lines <utf8-input> <utf8-output>', file=sys.stderr)
        return 2
    try:
        output = number_lines(open(sys.argv[1]).read())
        write_text(sys.argv[2], output)
        print(len(output))
    except OSError:
        print('file error', file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
